/* Graphic Design in 15 Days — study site
 * Plain JS, no build step. Content comes from data.js (generated by build.py).
 */
(function () {
  'use strict';

  var COURSE = window.COURSE || { meta: { sections: [] }, days: [], appendix: { sections: [] } };
  var DAYS = COURSE.days || [];
  var DAY_NUMBERS = DAYS.map(function (d) {
    return d.n;
  });

  var STORE = {
    doneKey: 'gdc.v1.done',
    taskKey: 'gdc.v1.tasks',
    lastKey: 'gdc.v1.last'
  };

  var $ = function (sel, root) {
    return (root || document).querySelector(sel);
  };

  var state = {
    done: readJSON(STORE.doneKey, []),
    tasks: readJSON(STORE.taskKey, {})
  };

  // ------------------------------------------------------------------ storage
  function readJSON(key, fallback) {
    try {
      var raw = localStorage.getItem(key);
      if (!raw) return fallback;
      var val = JSON.parse(raw);
      return val === null || val === undefined ? fallback : val;
    } catch (e) {
      return fallback;
    }
  }

  function writeJSON(key, val) {
    try {
      localStorage.setItem(key, JSON.stringify(val));
    } catch (e) {
      /* private mode quota — study still works, progress just won't persist */
    }
  }

  function isDone(n) {
    return state.done.indexOf(n) !== -1;
  }

  function toggleDone(n, force) {
    var has = isDone(n);
    var want = typeof force === 'boolean' ? force : !has;
    if (want && !has) state.done.push(n);
    if (!want && has) state.done = state.done.filter(function (x) {
      return x !== n;
    });
    state.done.sort(function (a, b) {
      return a - b;
    });
    writeJSON(STORE.doneKey, state.done);
    paintProgress();
    paintDrawerProgress();
    paintDoneButton(n);
  }

  function pad(n) {
    return n < 10 ? '0' + n : '' + n;
  }

  function escapeHtml(s) {
    return String(s)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  // ------------------------------------------------------------------ routing
  function route() {
    var hash = location.hash.replace(/^#\/?/, '');
    if (!hash) hash = 'start';

    if (hash.indexOf('day/') === 0) {
      var n = parseInt(hash.slice(4), 10);
      var day = getDay(n);
      if (day) return renderDay(day);
      location.replace('#/start');
      return;
    }
    if (hash === 'appendix') return renderDoc(COURSE.appendix, 'Appendix');
    if (hash === 'start') return renderStart();
    renderStart();
  }

  function getDay(n) {
    for (var i = 0; i < DAYS.length; i++) if (DAYS[i].n === n) return DAYS[i];
    return null;
  }

  function go(hash) {
    if (location.hash === hash) route();
    else location.hash = hash;
  }

  function scrollTop() {
    window.scrollTo({ top: 0, behavior: 'auto' });
    var main = $('#main');
    if (main) main.focus({ preventScroll: true });
  }

  // ------------------------------------------------------------------ progress
  function paintProgress() {
    var total = DAYS.length || 15;
    var done = state.done.filter(function (n) {
      return DAY_NUMBERS.indexOf(n) !== -1;
    }).length;
    var pct = total ? done / total : 0;
    var ring = $('#ringFg');
    if (ring) {
      var c = 2 * Math.PI * 15;
      ring.style.strokeDasharray = c.toFixed(2);
      ring.style.strokeDashoffset = (c * (1 - pct)).toFixed(2);
    }
    var label = $('#progressText');
    if (label) label.textContent = done + '/' + total;
    var sub = $('#brandSub');
    if (sub) {
      sub.textContent = done === 0 ? 'Phone-only · beginner → advanced' : done + ' of ' + total + ' days complete';
    }
    var pill = $('#progressPill');
    if (pill) pill.setAttribute('aria-label', done + ' of ' + total + ' days complete');
  }

  function paintDrawerProgress() {
    var links = document.querySelectorAll('.drawer-link[data-day]');
    for (var i = 0; i < links.length; i++) {
      var n = parseInt(links[i].getAttribute('data-day'), 10);
      links[i].classList.toggle('done', isDone(n));
    }
  }

  function paintDoneButton(n) {
    var btn = $('#doneBtn');
    if (!btn) return;
    var done = isDone(n);
    btn.classList.toggle('is-done', done);
    btn.textContent = done ? '✓ Day complete' : 'Mark day done';
    btn.setAttribute('aria-pressed', done ? 'true' : 'false');
  }

  // ------------------------------------------------------------------ views
  function renderStart() {
    document.title = 'Graphic Design in 15 Days · Phone-only course';
    var totalTasks = 0;
    var nextDay = null;
    for (var i = 0; i < DAYS.length; i++) if (!isDone(DAYS[i].n)) {
      nextDay = DAYS[i];
      break;
    }

    var HIDDEN_ON_SITE = ['the-fifteen-days-at-a-glance'];
    var metaHtml = (COURSE.meta.sections || [])
      .filter(function (s) {
        return HIDDEN_ON_SITE.indexOf(s.id) === -1;
      })
      .map(function (s) {
        return (
          '<section id="' +
          escapeHtml(s.id) +
          '"><h2>' +
          escapeHtml(s.title) +
          '</h2>' +
          s.html +
          '</section>'
        );
      })
      .join('');

    var weeks = [
      { label: 'Week 1', name: 'Foundations', range: [1, 5], blurb: 'Vocabulary, seeing, composition, colour, type.' },
      { label: 'Week 2', name: 'Craft', range: [6, 10], blurb: 'Typesetting, photo editing, logo, brand, print.' },
      { label: 'Week 3', name: 'Advanced', range: [11, 15], blurb: 'Art direction, content systems, UI, clients, portfolio.' }
    ];

    var cards = weeks
      .map(function (w) {
        var days = DAYS.filter(function (d) {
          return d.n >= w.range[0] && d.n <= w.range[1];
        });
        var doneCount = days.filter(function (d) {
          return isDone(d.n);
        }).length;
        var inner = days
          .map(function (d) {
            return (
              '<a class="card' +
              (isDone(d.n) ? ' is-done' : '') +
              '" href="#/day/' +
              d.n +
              '">' +
              '<div class="card-top"><b>Day ' +
              d.n +
              '</b><small>' +
              escapeHtml(d.phase) +
              '</small>' +
              (isDone(d.n) ? '<small style="color:var(--green);margin-left:auto">done</small>' : '') +
              '</div>' +
              '<p>' +
              escapeHtml(d.title) +
              '</p></a>'
            );
          })
          .join('');
        return (
          '<div class="week-group"><h2 style="margin-top:34px">' +
          w.label +
          ' · ' +
          w.name +
          '</h2><p style="color:var(--ink-soft);font-size:14.5px;margin-bottom:12px">' +
          w.blurb +
          ' <strong>' +
          doneCount +
          '/' +
          days.length +
          '</strong> done</p>' +
          inner +
          '</div>'
        );
      })
      .join('');

    var heroCta = nextDay
      ? '<a class="primary-btn" href="#/day/' + nextDay.n + '">' + (state.done.length ? 'Continue' : 'Start') + ' Day ' + nextDay.n + ' →</a>'
      : '<a class="primary-btn" href="#/day/15">Revisit the capstone →</a>';

    $('#view').innerHTML =
      '<div class="hero">' +
      '<p class="eyebrow">A fifteen-day, phone-only course</p>' +
      '<h1>Graphic design, from zero to portfolio</h1>' +
      '<p class="lede">Fifteen study sessions of 2 hours 30 minutes, Saturday to Wednesday, with Thursday and Friday off. Every day has practice, questions, a client scenario, and research to carry into the next day.</p>' +
      '<div class="stat-row">' +
      '<div class="stat"><b>15</b><span>STUDY DAYS</span></div>' +
      '<div class="stat"><b>2.5h</b><span>PER DAY</span></div>' +
      '<div class="stat"><b>0</b><span>LAPTOP NEEDED</span></div>' +
      '</div>' +
      '<div class="cta-row">' +
      heroCta +
      '<a class="secondary-btn" href="#/appendix">Templates &amp; glossary</a>' +
      '</div>' +
      '</div>' +
      '<section id="weeks"><h2>The three weeks</h2>' +
      cards +
      '</section>' +
      metaHtml +
      '<div class="day-foot"><p><strong>Printing it?</strong> Use your browser’s print option on any page — the layout is print-ready. The complete course is also available as a single Markdown document in the repository.</p></div>';

    $('#daynav').hidden = true;
    scrollTop();
  }

  function renderDay(day) {
    document.title = 'Day ' + day.n + ' · ' + day.title;
    try {
      localStorage.setItem(STORE.lastKey, String(day.n));
    } catch (e) {}

    var toc = day.sections
      .map(function (s) {
        return '<a href="#' + escapeHtml(s.id) + '" data-jump="' + escapeHtml(s.id) + '">' + escapeHtml(s.title) + '</a>';
      })
      .join('');

    var body = day.sections
      .map(function (s) {
        return (
          '<section id="' +
          escapeHtml(s.id) +
          '"><h2>' +
          escapeHtml(s.title) +
          '</h2>' +
          s.html +
          '</section>'
        );
      })
      .join('');

    var badges = (day.badges || [])
      .map(function (b) {
        return '<span class="pill">' + escapeHtml(b) + '</span>';
      })
      .join('');

    $('#view').innerHTML =
      '<div class="day-head">' +
      '<div class="kicker">' +
      '<span class="pill accent">Day ' + day.n + ' of ' + DAYS.length + '</span>' +
      '<span class="pill">' +
      escapeHtml(day.phase) +
      '</span>' +
      (day.slot ? '<span class="pill">' + escapeHtml(day.slot) + '</span>' : '') +
      (isDone(day.n) ? '<span class="pill done">✓ complete</span>' : '') +
      '</div>' +
      '<h1>' +
      escapeHtml(day.title) +
      '</h1>' +
      '<div class="day-meta">' +
      badges +
      (day.metaHtml || '') +
      '</div>' +
      '</div>' +
      '<nav class="day-toc" aria-label="On this page">' +
      toc +
      '</nav>' +
      '<div class="day-body">' +
      body +
      '</div>' +
      '<div class="day-foot"><p><strong>Before you close this page:</strong> export your work, file it in <code>03-Final</code>, and write the two-line log entry. Tomorrow’s research task is in the last section — write it on a fresh note now, not in the morning.</p></div>';

    restoreTasks(day.n);
    bindJumpLinks();
    paintDoneButton(day.n);

    var nav = $('#daynav');
    nav.hidden = false;
    var idx = DAY_NUMBERS.indexOf(day.n);
    var prev = idx > 0 ? getDay(DAY_NUMBERS[idx - 1]) : null;
    var next = idx < DAY_NUMBERS.length - 1 ? getDay(DAY_NUMBERS[idx + 1]) : null;

    var prevBtn = $('#prevBtn');
    var nextBtn = $('#nextBtn');
    prevBtn.disabled = !prev;
    nextBtn.disabled = !next;
    prevBtn.textContent = prev ? '← Day ' + prev.n : '← Start';
    nextBtn.textContent = next ? 'Day ' + next.n + ' →' : 'Appendix →';

    prevBtn.onclick = function () {
      go(prev ? '#/day/' + prev.n : '#/start');
    };
    nextBtn.onclick = function () {
      go(next ? '#/day/' + next.n : '#/appendix');
    };
    $('#doneBtn').onclick = function () {
      toggleDone(day.n);
      route();
    };

    updateActiveLink(day.n);
    scrollTop();
  }

  function renderDoc(doc, label) {
    document.title = label + ' · Graphic Design in 15 Days';
    var body = (doc.sections || [])
      .map(function (s) {
        return (
          '<section id="' +
          escapeHtml(s.id) +
          '"><h2>' +
          escapeHtml(s.title) +
          '</h2>' +
          s.html +
          '</section>'
        );
      })
      .join('');
    $('#view').innerHTML =
      '<p class="eyebrow">' +
      escapeHtml(label) +
      '</p><h1>' +
      escapeHtml(doc.title || label) +
      '</h1>' +
      body;
    $('#daynav').hidden = true;
    updateActiveLink(null);
    scrollTop();
  }

  function restoreTasks(n) {
    var boxes = document.querySelectorAll('[data-key]');
    for (var i = 0; i < boxes.length; i++) {
      var key = boxes[i].getAttribute('data-key');
      boxes[i].checked = !!state.tasks[key];
      boxes[i].addEventListener('change', onTaskChange);
    }
  }

  function onTaskChange(e) {
    var box = e.target;
    var key = box.getAttribute('data-key');
    if (box.checked) state.tasks[key] = 1;
    else delete state.tasks[key];
    writeJSON(STORE.taskKey, state.tasks);
  }

  function bindJumpLinks() {
    var links = document.querySelectorAll('[data-jump]');
    for (var i = 0; i < links.length; i++) {
      links[i].addEventListener('click', function (ev) {
        ev.preventDefault();
        var target = document.getElementById(this.getAttribute('data-jump'));
        if (target) {
          var y = target.getBoundingClientRect().top + window.pageYOffset - 64;
          window.scrollTo({ top: y, behavior: 'smooth' });
        }
      });
    }
  }

  // ------------------------------------------------------------------ drawer
  function buildDrawer() {
    var html = '<a class="drawer-link" data-route="start" href="#/start"><span class="dnum">→</span>Start here<span class="tick"></span></a>';

    var weeks = [
      { label: 'Week 1 — Foundations', range: [1, 5] },
      { label: 'Week 2 — Craft', range: [6, 10] },
      { label: 'Week 3 — Advanced', range: [11, 15] }
    ];

    weeks.forEach(function (w) {
      var days = DAYS.filter(function (d) {
        return d.n >= w.range[0] && d.n <= w.range[1];
      });
      if (!days.length) return;
      html += '<p class="drawer-group">' + escapeHtml(w.label) + '</p>';
      days.forEach(function (d) {
        html +=
          '<a class="drawer-link" data-day="' +
          d.n +
          '" href="#/day/' +
          d.n +
          '"><span class="dnum">' +
          pad(d.n) +
          '</span><span>' +
          escapeHtml(d.title) +
          '</span><span class="tick">✓</span></a>';
      });
    });

    html +=
      '<p class="drawer-group">Reference</p><a class="drawer-link" data-route="appendix" href="#/appendix"><span class="dnum">§</span>Appendix &amp; templates</a>';

    $('#drawerBody').innerHTML = html;
    paintDrawerProgress();
  }

  function updateActiveLink(n) {
    var links = document.querySelectorAll('.drawer-link');
    for (var i = 0; i < links.length; i++) {
      var linkDay = links[i].getAttribute('data-day');
      var routeName = links[i].getAttribute('data-route');
      var active =
        (n !== null && linkDay && parseInt(linkDay, 10) === n) ||
        (n === null && routeName && location.hash.indexOf(routeName) !== -1);
      links[i].classList.toggle('active', !!active);
    }
  }

  function openDrawer(open) {
    var drawer = $('#drawer');
    var scrim = $('#scrim');
    var btn = $('#menuBtn');
    drawer.classList.toggle('open', open);
    drawer.setAttribute('aria-hidden', open ? 'false' : 'true');
    btn.setAttribute('aria-expanded', open ? 'true' : 'false');
    document.body.classList.toggle('no-scroll', open);
    if (scrim.hidden) scrim.hidden = false;
    requestAnimationFrame(function () {
      scrim.classList.toggle('show', open);
    });
    if (!open) setTimeout(function () {
      scrim.hidden = true;
    }, 200);
  }

  // ------------------------------------------------------------------ init
  function init() {
    buildDrawer();
    paintProgress();

    $('#menuBtn').addEventListener('click', function () {
      openDrawer(true);
    });
    $('#closeBtn').addEventListener('click', function () {
      openDrawer(false);
    });
    $('#scrim').addEventListener('click', function () {
      openDrawer(false);
    });
    $('#drawerBody').addEventListener('click', function (e) {
      var link = e.target.closest('.drawer-link');
      if (link) openDrawer(false);
    });
    $('#resetBtn').addEventListener('click', function () {
      if (!window.confirm('Clear all day ticks and checkboxes? This cannot be undone.')) return;
      state.done = [];
      state.tasks = {};
      writeJSON(STORE.doneKey, state.done);
      writeJSON(STORE.taskKey, state.tasks);
      paintProgress();
      paintDrawerProgress();
      route();
    });

    document.addEventListener('keydown', function (e) {
      if (e.metaKey || e.ctrlKey || e.altKey) return;
      var tag = (e.target.tagName || '').toLowerCase();
      if (tag === 'input' || tag === 'textarea') return;
      if (e.key === 'Escape') openDrawer(false);
      if (e.key === 'ArrowRight' && !$('#nextBtn').disabled && !$('#daynav').hidden) {
        $('#nextBtn').click();
      }
      if (e.key === 'ArrowLeft' && !$('#prevBtn').disabled && !$('#daynav').hidden) {
        $('#prevBtn').click();
      }
    });

    window.addEventListener('hashchange', route);
    route();
    paintProgress();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
